import json, base64
b64 = ''
sa = json.loads(base64.b64decode(b64).decode())
pk = sa['private_key']
b = pk.encode('utf-8')
print(f'Length: {len(b)}')
print(f'Header present: {b"BEGIN PRIVATE KEY" in b}')
print(f'Footer present: {b"END PRIVATE KEY" in b}')
print(f'Literal backslash-n count: {b.count(b"\\\\n")}')
print(f'Actual 0x0a count: {b.count(bytes([10]))}')
lines = pk.split('\n')
for i, line in enumerate(lines):
    if len(line) > 64 and line.strip() and 'PRIVATE KEY' not in line:
        print(f'LINE {i}: len={len(line)} (max PEM is 64)')
